structure.mermaidSource:
flowchart TD
  start(["Início: Forma Verbal em Exame"]) --> dec_locucao{"O verbo compõe uma locução verbal?"}
  dec_locucao -- "Sim" --> dec_papel_loc{"Qual o papel estrutural na locução?"}
  dec_papel_loc -- "'Haver' auxiliar de verbo principal pessoal" --> res_pessoal_aux["Verbo Pessoal (Auxiliar flexiona com o sujeito)"]
  dec_papel_loc -- "Verbo principal é impessoal" --> res_loc_impessoal["Locução Impessoal (Auxiliar invariável na 3ª sing.)"]
  dec_papel_loc -- "Locução comum (verbo pessoal)" --> proc_pergunta["Formular pergunta: 'Quem / O que é que [verbo]?'"]
  dec_locucao -- "Não (Verbo Isolado)" --> proc_pergunta
  proc_pergunta --> dec_sujeito_exp{"Há termo substantivo expresso ou resgatável contextualmente?"}
  dec_sujeito_exp -- "Sim" --> res_pessoal_exp["Verbo Pessoal (Sujeito Expresso ou Oculto)"]
  dec_sujeito_exp -- "Não" --> dec_3pl_sem_ant{"Verbo na 3ª pessoa do plural sem antecedente?"}
  dec_3pl_sem_ant -- "Sim" --> res_pessoal_indet["Verbo Pessoal (Sujeito Indeterminado)"]
  dec_3pl_sem_ant -- "Não" --> dec_regras_impes{"Enquadra-se em impessoalidade pura? (Natureza, Haver, Fazer, Passar de)"}
  dec_regras_impes -- "Sim" --> res_impessoal_puro["Verbo Impessoal (Oração Sem Sujeito - Invariável 3ª sing.)"]
  dec_regras_impes -- "Não" --> res_sentido_figurado["Verbo Pessoal (Sentido figurado / Reavaliar contexto)"]

flowchart TD
  start(["Início: Ocorrência do Verbo 'Haver'"]) --> dec_associado{"O verbo 'haver' está acompanhado de particípio ou infinitivo preposicionado?"}
  dec_associado -- "Não" --> proc_pleno["Analisar 'haver' como verbo principal pleno"]
  proc_pleno --> dec_sentido_pleno{"Equivale a 'existir/ocorrer' ou exprime tempo decorrido?"}
  dec_sentido_pleno -- "Sim" --> res_impes_pleno["Verbo Impessoal (Sem sujeito, invariável na 3ª sing.)"]
  dec_sentido_pleno -- "Não" --> res_pessoal_pleno["Verbo Pessoal Pleno (Flexiona com o sujeito: ter, conseguir, portar-se)"]
  dec_associado -- "Sim" --> proc_auxiliar["Identificar 'haver' como verbo auxiliar na locução"]
  proc_auxiliar --> dec_sujeito_princ{"O verbo principal possui sujeito sintático (expresso ou elíptico)?"}
  dec_sujeito_princ -- "Sim" --> res_haver_pessoal["Verbo 'Haver' Pessoal (Concorda em número e pessoa com o sujeito)"]
  dec_sujeito_princ -- "Não" --> res_haver_impes["Verbo 'Haver' Auxiliar de Verbo Impessoal (Invariável na 3ª sing.)"]

flowchart TD
  start(["Início: Oração com Verbo Ser (3ª Pessoa)"]) --> proc_isolar["1. Isolar Oração com 'É'"]
  proc_isolar --> proc_pergunta["2. Formular Pergunta: 'O que é + predicativo?'"]
  proc_pergunta --> dec_resposta{"A pergunta encontra resposta no contexto?"}
  dec_resposta -- "Não" --> dec_tempo{"O predicativo indica tempo cronológico puro?"}
  dec_resposta -- "Sim" --> dec_tipo_resposta{"A resposta é uma oração (com verbo/infinitivo/que)?"}
  dec_tempo -- "Sim (ex.: 'É tarde')" --> res_impessoal_tempo["Resultado: Verbo Impessoal (Indicação Cronológica)"]
  dec_tempo -- "Não" --> res_impessoal_outros["Resultado: Verbo Impessoal por Ausência de Agente"]
  dec_tipo_resposta -- "Sim (oração introduzida por infinitivo ou que)" --> res_sujeito_oracional["Resultado: Verbo Pessoal com Sujeito Oracional"]
  dec_tipo_resposta -- "Não (substantivo / pronome simples)" --> res_sujeito_simples["Resultado: Verbo Pessoal com Sujeito Simples"]

flowchart TD
  start(["Início: Diagnóstico do Estudante de Concursos"]) --> dec_edital{"O edital do concurso já foi publicado?"}
  dec_edital -- "Não (Pré-Edital)" --> dec_base_teorica{"A base teórica estrutural progressiva já foi concluída?"}
  dec_edital -- "Sim (Pós-Edital)" --> dec_prontidao_pos{"Possui base teórica prévia consolidada (>75% de acertos)?"}
  dec_base_teorica -- "Não (em construção)" --> res_c1["Círculo 1: Base Teórica Sequencial\n(Morfologia a Pontuação sem foco em banca)"]
  dec_base_teorica -- "Sim (teoria finalizada)" --> res_c2["Círculo 2: Revisão Tópica Orientada por Questões\n(Baterias temáticas com professor / pegadinhas)"]
  dec_prontidao_pos -- "Sim (base consolidada)" --> res_c3["Círculo 3: Reta Final Específica da Banca\n(Provas completas recentes da organizadora)"]
  dec_prontidao_pos -- "Não (lacunas graves)" --> res_hibrido["Plano Híbrido Emergencial\n(Círculo 2 Tópico + Simulação Círculo 3)"]
